/**
 * Browser → Ollama on the user's laptop (opt-in). Requires Ollama with CORS for dev origin.
 * Set OLLAMA_ORIGINS=http://localhost:4030 in ~/.ollama or environment.
 */

const DEFAULT_BASE = import.meta.env.VITE_LOCAL_LLM_URL || 'http://127.0.0.1:11434';
const DEFAULT_MODEL = import.meta.env.VITE_LOCAL_LLM_MODEL || 'qwen2.5-coder:1.5b';

export async function probeLocalLlm(baseUrl = DEFAULT_BASE) {
  try {
    const res = await fetch(`${baseUrl.replace(/\/$/, '')}/api/tags`, {
      method: 'GET',
      signal: AbortSignal.timeout(4000),
    });
    if (!res.ok) return { available: false, models: [] };
    const data = await res.json();
    return {
      available: true,
      models: (data.models || []).map((m) => m.name),
      baseUrl: baseUrl.replace(/\/$/, ''),
    };
  } catch {
    return { available: false, models: [] };
  }
}

export async function generateLocalText(prompt, {
  baseUrl = DEFAULT_BASE,
  model = DEFAULT_MODEL,
  temperature = 0.1,
  maxTokens = 2048,
} = {}) {
  const res = await fetch(`${baseUrl.replace(/\/$/, '')}/api/generate`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model,
      prompt,
      stream: false,
      options: { temperature, num_predict: maxTokens },
    }),
  });

  if (!res.ok) {
    const err = await res.text();
    throw new Error(`Local Ollama error: ${err.slice(0, 200)}`);
  }

  const data = await res.json();
  return data.response || '';
}

/** Strip markdown fences if model disobeys */
export function extractRawJson(text) {
  if (!text) return null;
  const trimmed = text.trim();
  const fence = trimmed.match(/```(?:json)?\s*([\s\S]*?)```/);
  const raw = fence ? fence[1].trim() : trimmed;
  try {
    return JSON.parse(raw);
  } catch {
    const start = raw.indexOf('{');
    const end = raw.lastIndexOf('}');
    if (start >= 0 && end > start) {
      try {
        return JSON.parse(raw.slice(start, end + 1));
      } catch {
        return null;
      }
    }
    return null;
  }
}

export { DEFAULT_BASE, DEFAULT_MODEL };
